/// <summary>
/// PaffH 18.11.21
/// display red X if blocked
/// </summary>
/// <returns>container</returns>
[SysClientCacheDataMethodAttribute]
public display container NDXIsBlocked()
{
    return NDXAddressTableHelper::NDXGetBlockedSymbol(this.Blocked);
}

/// <summary>
/// COC of modifiedField method
/// </summary>
/// <param name = "_fieldId">_fieldId</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(CustTable, SalesDistrictId):
            if(this.MainContactWorker != this.orig().MainContactWorker || this.SalesGroup != this.orig().SalesGroup || this.SalesDistrictId != this.orig().SalesDistrictId)
            {
                CustTable::NDX_AddSalesUnitHistory(this.orig());
            }
            break;
    }
}

/// <summary>
/// Add Sales unit history record
/// </summary>
/// <param name = "custTable">CustTable record</param>
static void NDX_AddSalesUnitHistory(CustTable custTable)
{
    NDXsmmSalesUnitHistory     nDX_smmSalesUnitHistory;

    nDX_smmSalesUnitHistory.RefRecIdCustTable               = custTable.RecId;
    nDX_smmSalesUnitHistory.smmBusRelAccResponsibleWorker   = custTable.MainContactWorker;
    nDX_smmSalesUnitHistory.smmSalesDistrictId              = custTable.SalesDistrictId;
    nDX_smmSalesUnitHistory.CommissSalesGroup               = custTable.SalesGroup;
    nDX_smmSalesUnitHistory.ToDate                          = DateTimeUtil::date(DateTimeUtil::utcNow());

    nDX_smmSalesUnitHistory.insert();
}

/// <summary>
/// find custtable
/// </summary>
/// <param name = "_accountNum">cust account</param>
/// <param name = "_company">company by NDXCompanyBe</param>
/// <returns>CustTable record</returns>
static CustTable NDX_findCustByCompany(AccountNum _accountNum, NDXCompanyBe _company)
{
    CustTable custTable;
    container conCompany;
    ;
    if (_company !=  NDXCompanyBe::WithoutAssignment && _company !=  NDXCompanyBe::AllCompanies)
    {
        conCompany = [NDXHelperCommon::NDXCompanys2CompanyId(_company)];
        select crosscompany:conCompany custTable where custTable.AccountNum == _accountNum;
    }
    return custTable;
}
